<?php require __DIR__.'/partials/header.php';$q=trim($_GET['q']??'');$cat=$_GET['categoria']??'';$sql='SELECT * FROM news WHERE 1';$a=[];if($q!==''){$sql.=' AND (title LIKE ? OR excerpt LIKE ?)';$a[]='%'.$q.'%';$a[]='%'.$q.'%';}if($cat!==''){$sql.=' AND category=?';$a[]=$cat;}$sql.=' ORDER BY published_at DESC';$st=$db->prepare($sql);$st->execute($a);$rows=$st->fetchAll();?><section class="page-hero"><div class="wrap"><span class="eyebrow">DAL CLUB</span><h1>ULTIME <em>NEWS</em></h1><p>Comunicazioni e aggiornamenti, con contenuti di prova identificati come DEMO.</p></div></section><section class="wrap section"><form class="filters"><input name="q" value="<?= e($q) ?>" placeholder="Cerca notizia..."><select name="categoria"><option value="">Tutte le categorie</option><?php foreach(['Prima Squadra','Partite','Mercato','Giovanili','Società'] as $c): ?><option <?= $cat===$c?'selected':'' ?>><?= e($c) ?></option><?php endforeach; ?></select><button class="btn btn-red">Cerca</button></form><div class="news-grid"><?php foreach($rows as $n): ?><article class="news-card"><a href="notizia.php?id=<?= (int)$n['id'] ?>"><div class="news-image" style="background-image:url('<?= e($n['image_url']?:'assets/images/basket.svg') ?>')"><span class="tag"><?= e($n['category']) ?></span></div><div class="news-copy"><small><?= e(date('d/m/Y',strtotime($n['published_at']))) ?> · <?= $n['is_demo']?'DEMO':'PUBBLICATA' ?></small><h3><?= e($n['title']) ?></h3><p><?= e($n['excerpt']) ?></p></div></a></article><?php endforeach; ?></div><?php if(!$rows): ?><p class="empty">Nessuna notizia trovata.</p><?php endif; ?></section><?php require __DIR__.'/partials/footer.php'; ?>